padElement.onpointerdown=e=>{if(paused||portraitBlocked||!E)return;e.preventDefault();if(joypad.start(e.pointerId,e.clientX,e.clientY,padElement.getBoundingClientRect())){padElement.setPointerCapture?.(e.pointerId);audioStart();paintPad();}};
