for(const id of ['gbA','gbB']){const b=$(id);b.onpointerdown=e=>{if(paused||portraitBlocked||b.disabled||!E)return;e.preventDefault();b.setPointerCapture?.(e.pointerId);pointers.set(e.pointerId,id);b.classList.add('held');audioStart();input[id==='gbA'?'action':(E.expedition||E.adventure)?'interact':'jump']=true;};const release=e=>{pointers.delete(e.pointerId);if(![...pointers.values()].includes(id))b.classList.remove('held');};b.onpointerup=release;b.onpointercancel=release;b.onlostpointercapture=release;}
